18	package org.apache.hadoop.ipc;
19	
20	import org.apache.hadoop.conf.Configuration;
21	import org.junit.Assert;
22	import org.junit.Test;
23	
24	import static org.apache.hadoop.fs.CommonConfigurationKeysPublic.HADOOP_CALLER_CONTEXT_SEPARATOR_KEY;
25	
26	public class TestCallerContext {
27	  @Test
28	  public void testBuilderAppend() {
29	    Configuration conf = new Configuration();
30	    conf.set(HADOOP_CALLER_CONTEXT_SEPARATOR_KEY, "$");
31	    CallerContext.Builder builder = new CallerContext.Builder(null, conf);
32	    CallerContext context = builder.append("context1")
33	        .append("context2").append("key3", "value3").build();
34	    Assert.assertEquals(true,
35	        context.getContext().contains("$"));
36	    String[] items = context.getContext().split("\\$");
37	    Assert.assertEquals(3, items.length);
38	    Assert.assertEquals("key3:value3", items[2]);
39	
40	    builder.append("$$");
41	    Assert.assertEquals("context1$context2$key3:value3$$$",
42	        builder.build().getContext());
43	  }
44	
45	  @Test(expected = IllegalArgumentException.class)
46	  public void testNewBuilder() {
47	    Configuration conf = new Configuration();
48	    // Set illegal separator.
49	    conf.set(HADOOP_CALLER_CONTEXT_SEPARATOR_KEY, "\t");
50	    CallerContext.Builder builder = new CallerContext.Builder(null, conf);
51	    builder.build();
52	  }
53	}
